import {engineInstaller} from './engine-install-ui.js';
import{readSourceZip,readSourceFolder,sourceBytes,sourceText}from'./source-archive.js';import{ENGINE_NAMES,featureProblems}from'./source-features.js';import{importSourceEntries,sourceInventory,prepareSourceExport}from'./source-project.js';import{pngSize,readRawSourceSprite}from'./source-assets.js';import{studioData,makeSpriteGroup,indexRGBA}from'./sprite-workbench.js';import{musicProfile,discoverMusicTarget}from'./music-assets.js';import{makeZip}from'./zip.js';
export function sourceWorkshop(api){
 const expanded=engineInstaller(api);const $=s=>document.querySelector(s),esc=api.esc,state={files:null,archiveId:null,inventory:null,tab:'features',query:'',category:'all',busy:false},settings=()=>api.project().sourceEngine;
 const task=fn=>async()=>{if(state.busy)return;state.busy=true;try{await fn();}catch(e){api.error(e);}finally{state.busy=false;}};
 function status(text){if($('#sourceStatus'))$('#sourceStatus').textContent=text;}
 async function attached(){const s=settings();if(!s){state.files=null;state.archiveId=null;return false;}if(state.archiveId!==s.archiveId){const record=await api.readSource(s.archiveId);if(!record){state.files=null;state.archiveId=null;return false;}state.files=new Map(record.entries);state.archiveId=s.archiveId;state.inventory=sourceInventory(state.files,s.engine);}return true;}
 async function open(tab=state.tab){state.tab=tab;await attached();render();}
 async function attach(entries,name){const result=await importSourceEntries(entries,name),old=settings();await api.writeSource({id:result.settings.archiveId,entries:[...result.files]});api.change(()=>api.project().sourceEngine=old?.archiveId===result.settings.archiveId?old:result.settings);Object.assign(state,{files:result.files,archiveId:result.settings.archiveId,inventory:result.inventory});api.refresh();render();api.toast('Source attached. Original files preserved.');}
 function render(){const s=settings(),ready=s&&state.files&&s.archiveId===state.archiveId;api.modal('Engine & source project',`<p>Use a compiled ROM for binary editing, or attach FireRed/Emerald decomp or CFRU source for engine configuration and asset replacements.</p><div class="studio-actions"><button id="sourceExpanded" type="button">Create expanded FireRed ROM</button><button id="sourceZip" type="button">Import source ZIP</button><button id="sourceFolder" type="button">Import source folder</button><button id="sourceBinary" type="button">Open / edit a GBA ROM</button></div><input id="sourceZipInput" type="file" accept=".zip,application/zip" hidden><input id="sourceFolderInput" type="file" webkitdirectory multiple hidden><p id="sourceStatus" role="status">${ready?esc(ENGINE_NAMES[s.engine])+' · '+esc(s.name)+' · '+state.files.size.toLocaleString()+' files':s?'Settings saved. Reattach the same source ZIP on this device to continue.':'Import the actual source project, not a compiled .gba file. GitHub ZIPs are supported.'}</p>${ready?`<div class="studio-tabs">${[['features','Features'],['sprites','Sprites'],['music','Music'],['build','Review & build']].map(([id,name])=>`<button data-source-tab="${id}" type="button" class="${id===state.tab?'active':''}">${name}</button>`).join('')}</div><div id="sourceContent"></div>`:''}<details><summary>Builds and compatibility</summary><p>Source changes export as a complete project ZIP with a build helper. Rebuild on a computer with the project toolchain, then reopen the resulting ROM here. Android does not contain a full C/assembly compiler.</p><p>Binary map/event edits and source changes have separate exports. Compile source first, then reopen its ROM for binary editing. Full source map/event authoring and automatic engine installation into arbitrary ROMs are not available.</p><p>Source files stay on this device. Project backups retain settings; export a source ZIP to back up the source files too.</p><p><a href="https://github.com/Shiny-Miner/CFRU-expansion" target="_blank" rel="noopener">Shiny’s CFRU Expansion</a> · <a href="https://github.com/Skeli789/Complete-Fire-Red-Upgrade" target="_blank" rel="noopener">CFRU</a> · <a href="https://github.com/pret/pokefirered" target="_blank" rel="noopener">FireRed decomp</a> · <a href="https://github.com/pret/pokeemerald" target="_blank" rel="noopener">Emerald decomp</a></p></details>`,null,'Done');
  $('#sourceExpanded').onclick=()=>expanded.open();$('#sourceZip').onclick=()=>$('#sourceZipInput').click();$('#sourceFolder').onclick=()=>$('#sourceFolderInput').click();$('#sourceBinary').onclick=()=>api.pickROM('game');$('#sourceZipInput').onchange=task(async()=>{const f=$('#sourceZipInput').files?.[0];if(f){status('Reading source ZIP…');await attach(await readSourceZip(await f.arrayBuffer(),{progress:status}),f.name);}});$('#sourceFolderInput').onchange=task(async()=>{const files=[...$('#sourceFolderInput').files];if(files.length)await attach(await readSourceFolder(files,{progress:status}),files[0].webkitRelativePath?.split('/')[0]||'Source project');});document.querySelectorAll('[data-source-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.sourceTab;render();});if(ready)({features,sprites,music,build}[state.tab]||features)();
 }
 function features(){const s=settings(),rows=state.inventory.features;$('#sourceContent').innerHTML=`<p>These switches come from this source’s configuration. Changes take effect after rebuilding. Locked options need additional source, hook or table changes.</p><div class="field-row"><label>Find a feature<input id="sourceFeatureSearch" type="search" value="${esc(state.query)}" placeholder="Followers, HM, debug, music…"></label><label>Category<select id="sourceFeatureCategory"><option value="all">All categories</option>${[...new Set(rows.map(r=>r.category))].sort().map(c=>`<option ${c===state.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div id="sourceFeatureIssues" role="status"></div><div id="sourceFeatureRows"></div><button id="sourceResetFeatures" type="button">Restore imported settings</button><details><summary>Features controlled by game events</summary><p>These symbols name saved flags or variables. Removing their definitions would break code that uses them. Enable them through engine event scripts or its debug menu.</p>${state.inventory.runtime.map(r=>`<p><b>${esc(r.label)}</b> · ${esc(r.symbol)} · ${r.kind} 0x${r.address.toString(16)}${r.symbol==='VAR_GAME_DIFFICULTY'?' · 0 Normal, 1 Easy, 2 Hard, 3 Expert':''}</p>`).join('')||'<p>No known runtime feature symbols found.</p>'}</details>`;
  function issues(){$('#sourceFeatureIssues').textContent=featureProblems(rows,s.features).join(' ');}function draw(){const visible=rows.filter(r=>(state.category==='all'||r.category===state.category)&&(r.label+' '+r.name+' '+r.description).toLowerCase().includes(state.query.toLowerCase()));$('#sourceFeatureRows').innerHTML=visible.map((r,i)=>{const value=Object.hasOwn(s.features,r.id)?s.features[r.id]:r.value;return`<article class="source-feature ${r.locked?'source-locked':''}"><label ${r.type==='boolean'?'class="check"':''}>${r.type==='boolean'?`<input type="checkbox" data-source-feature="${i}" ${value?'checked':''} ${r.locked?'disabled':''}>`:''}<b>${esc(r.label)}</b>${r.type==='number'?`<input data-source-feature="${i}" type="number" min="${r.min}" max="${r.max}" value="${value}" ${r.locked?'disabled':''}>`:''}</label><p>${esc(r.reason||r.description||'Build-time source configuration.')}</p><small>${esc(r.name)} · ${esc(r.path)}${Object.hasOwn(s.features,r.id)?' · modified':''}</small></article>`;}).join('')||'<p>No matching switches. Vanilla decomps have few optional features; an expansion exposes its actual configuration.</p>';document.querySelectorAll('[data-source-feature]').forEach(input=>input.onchange=()=>{const r=visible[+input.dataset.sourceFeature],value=r.type==='boolean'?input.checked:Number(input.value);if(r.type==='number'&&(!Number.isInteger(value)||value<r.min||value>r.max)){api.error(Error('Use '+r.min+'–'+r.max));return;}api.change(()=>{if(value===r.value)delete s.features[r.id];else s.features[r.id]=value;});issues();api.refresh();});issues();}$('#sourceFeatureSearch').oninput=e=>{state.query=e.target.value;draw();};$('#sourceFeatureCategory').onchange=e=>{state.category=e.target.value;draw();};$('#sourceResetFeatures').onclick=()=>{api.change(()=>s.features={});draw();api.refresh();};draw();
 }
 function sprites(){const s=settings(),groups=api.project().spriteStudio?.groups||[];$('#sourceContent').innerHTML=`<p>Read source artwork into the sprite workshop, then bind edited views or palettes to existing source files. Exact dimensions and frame counts are checked. New species require the engine’s own data definitions.</p><label>Find a source asset<input id="sourceAssetSearch" type="search" placeholder="Bulbasaur, trainer, follower…"></label><label>Source graphics file<select id="sourceAssetPath"></select></label><div class="studio-actions"><button id="sourceReadSprite" type="button">Read source sprite</button><button id="sourceOpenSprites" type="button">Sprite workshop</button></div><label>Sprite group<select id="sourceSpriteGroup">${groups.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select></label><div class="field-row"><label>View<select id="sourceSpriteRole"></select></label><label>Palette<select id="sourceSpritePalette"><option value="normal">Normal</option><option value="shiny">Shiny</option></select></label></div><button id="sourceBindSprite" type="button" ${groups.length?'':'disabled'}>Bind selected source file</button><h3>Queued replacements</h3>${s.sprites.map((b,i)=>`<article class="studio-record"><span><b>${esc(b.path)}</b><small>${esc(groups.find(g=>g.id===b.groupId)?.name||'Missing group')} · ${esc(b.role)} · ${b.shiny?'shiny':'normal'}</small></span><button type="button" data-remove-sprite="${i}">Remove</button></article>`).join('')||'<p>No source sprite replacements queued.</p>'}`;
  function list(){const files=state.inventory.graphics.filter(p=>p.toLowerCase().includes($('#sourceAssetSearch').value.toLowerCase()));$('#sourceAssetPath').innerHTML=files.slice(0,500).map(p=>`<option>${esc(p)}</option>`).join('');status(files.length>500?'Showing 500 matches. Search to narrow the list.':ENGINE_NAMES[s.engine]+' · '+files.length+' graphics matches');}function roles(){const g=groups.find(g=>g.id===$('#sourceSpriteGroup').value);$('#sourceSpriteRole').innerHTML=Object.keys(g?.views||{}).map(r=>`<option>${esc(r)}</option>`).join('');}$('#sourceAssetSearch').oninput=list;list();$('#sourceSpriteGroup').onchange=roles;roles();$('#sourceOpenSprites').onclick=()=>api.sprites().open();$('#sourceReadSprite').onclick=task(()=>readSprite($('#sourceAssetPath').value));$('#sourceBindSprite').onclick=()=>{try{const path=$('#sourceAssetPath').value;if(!path)throw Error('Choose a source file.');const binding={path,groupId:$('#sourceSpriteGroup').value,role:$('#sourceSpriteRole').value,shiny:$('#sourceSpritePalette').value==='shiny'},next=[...s.sprites.filter(b=>b.path!==path),binding];prepareSourceExport(state.files,{...s,sprites:next,music:[]},api.project());api.change(()=>s.sprites=next);api.refresh();render();}catch(e){api.error(e);}};document.querySelectorAll('[data-remove-sprite]').forEach(b=>b.onclick=()=>{api.change(()=>s.sprites.splice(+b.dataset.removeSprite,1));api.refresh();render();});
 }
 async function readSprite(path){if(!path||!/\.(png|4bpp)(\.lz)?$/.test(path))throw Error('Choose PNG or 4bpp graphics to read.');const bytes=state.files.get(path),png=path.endsWith('.png'),compressed=path.endsWith('.lz'),size=png?pngSize(bytes):{width:64,height:64},pals=state.inventory.graphics.filter(p=>/\.gbapal(\.lz)?$/.test(p));api.modal('Read source sprite',`<p>${esc(path)}</p><label>View<select id="sourceReadRole">${['front','back','icon','overworld','portrait','item'].map(r=>`<option>${r}</option>`).join('')}</select></label><div class="field-row"><label>Frame width<input id="sourceFrameW" type="number" value="${Math.min(size.width,64)}" min="8" max="128" step="8"></label><label>Frame height<input id="sourceFrameH" type="number" value="${Math.min(size.height,64)}" min="8" max="128" step="8"></label><label>Frames<input id="sourceFrameCount" type="number" value="${png?Math.max(1,Math.ceil(size.height/Math.min(size.height,64))):1}" min="1" max="64"></label></div>${png?'':`<label>Palette source<select id="sourceReadPalette">${pals.map(p=>`<option>${esc(p)}</option>`).join('')}</select></label>`}<p>Frames are stacked vertically. Match the source dimensions and frame count when replacing it.</p>`,async()=>{const width=+$('#sourceFrameW').value,height=+$('#sourceFrameH').value,count=+$('#sourceFrameCount').value,role=$('#sourceReadRole').value;if(![width,height].every(n=>Number.isInteger(n)&&n>=8&&n<=128&&n%8===0)||!Number.isInteger(count)||count<1||count>64)throw Error('Use 8–128 pixel frame dimensions and 1–64 frames.');let view,palette;if(png){if(size.width!==width||size.height!==height*count)throw Error('Frames must exactly fill the source PNG.');const image=await loadImage(bytes),canvas=document.createElement('canvas');canvas.width=size.width;canvas.height=size.height;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);const indexed=indexSourcePNG(bytes,ctx.getImageData(0,0,size.width,size.height).data);palette=indexed.palette;view={width,height,frames:Array.from({length:count},(_,i)=>indexed.pixels.slice(i*width*height,(i+1)*width*height))};}else{const path=$('#sourceReadPalette').value;if(!path)throw Error('Choose a 16-colour gbapal source.');const decoded=readRawSourceSprite(bytes,state.files.get(path),{width,height,frames:count,compressed,paletteCompressed:path.endsWith('.lz')});palette=decoded.palette;view={width,height,frames:decoded.frames};}const g=makeSpriteGroup(path.split('/').at(-1).split('.')[0],{palette,shiny:palette});g.views={[role]:view};api.change(()=>studioData(api.project()).groups.push(g));api.refresh();api.sprites().open({kind:'custom',id:g.id,side:role});return false;},'Open in sprite workshop');}
 function musicLimit(){const session=api.session();return session?(musicProfile(session.id)||discoverMusicTarget(session.reader))?.count:undefined;}
 function music(){const s=settings(),tracks=api.project().authoring?.music||[],cfru=['cfru','shiny'].includes(s.engine),limit=cfru?musicLimit():undefined,slots=state.inventory.songs.filter(slot=>!cfru||Number.isInteger(limit)&&Number(slot.id)<limit);$('#sourceContent').innerHTML=`<p>Replace an existing source song with a Music Studio track. Exports include its loop, instruments and referenced samples. Original game song slots keep their IDs.</p>${cfru?`<p>${Number.isInteger(limit)?'Opened ROM has '+limit+' verified song slots.':'Open the target GBA ROM to verify song slots. CFRU source export does not expand song tables.'}</p>`:''}<label>Music Studio track<select id="sourceMusicTrack">${tracks.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></label><label>Replace source song<select id="sourceMusicSlot">${slots.map(slot=>`<option value="${esc(slot.id)}">${esc(slot.label)}</option>`).join('')}</select></label><div class="studio-actions"><button id="sourceBindMusic" type="button" ${tracks.length&&slots.length?'':'disabled'}>Bind song replacement</button><button id="sourceMusicMaker" type="button">Music Studio</button>${cfru?'<button id="sourceMusicROM" type="button">Open target ROM</button>':''}</div><h3>Queued songs</h3>${s.music.map((b,i)=>`<article class="studio-record"><span><b>${esc(tracks.find(t=>t.id===b.trackId)?.name||'Missing track')}</b><small>${esc(state.inventory.songs.find(slot=>slot.id===b.slot)?.label||b.slot)}</small></span><button type="button" data-remove-music="${i}">Remove</button></article>`).join('')||'<p>No source music replacements queued.</p>'}`;$('#sourceMusicMaker').onclick=()=>api.music().open();if($('#sourceMusicROM'))$('#sourceMusicROM').onclick=()=>api.pickROM('source');$('#sourceBindMusic').onclick=()=>{const trackId=$('#sourceMusicTrack').value,slot=$('#sourceMusicSlot').value;api.change(()=>s.music=[...s.music.filter(b=>b.slot!==slot),{trackId,slot}]);api.refresh();render();};document.querySelectorAll('[data-remove-music]').forEach(b=>b.onclick=()=>{api.change(()=>s.music.splice(+b.dataset.removeMusic,1));api.refresh();render();});}
 function build(){const s=settings();let report,error;try{report=prepareSourceExport(state.files,s,api.project(),{songLimit:s.music.length?musicLimit():undefined}).report;}catch(e){error=e.message;}$('#sourceContent').innerHTML=`<p>Export the attached source with your selected switches and assets. Original source maps/events are preserved. The ZIP also carries an editable Studio project snapshot; this is a backup, not a conversion into source map files. Keep a portable project backup for referenced artwork. Binary map edits have a separate ROM export.</p>${error?`<p class="studio-status needs-attention">${esc(error)}</p>`:`<p>${report.changes.length} source files will change.</p><div class="source-change-list">${report.changes.map(c=>`<p><b>${esc(c.kind)}</b> · ${esc(c.path)} · ${c.bytes.toLocaleString()} bytes</p>`).join('')||'<p>No changes queued.</p>'}</div>`}<button id="sourceExport" type="button" class="primary" ${error?'disabled':''}>Export source project ZIP</button><ol><li>Extract on a computer with the project toolchain.</li><li>Check prerequisites: <code>python3 studio/build-source-project.py</code></li><li>Rebuild with <code>--build</code>${['cfru','shiny'].includes(s.engine)?' and <code>--rom /path/to/BPRE0.gba</code>':''} to create <code>Studio_Build.gba</code>.</li><li>Open the rebuilt ROM here for binary editing and playtesting.</li></ol><p>Only build source you trust. The app never executes imported scripts. Source credits and licences are preserved.</p>`;$('#sourceExport').onclick=task(async()=>{status('Preparing source export…');const result=prepareSourceExport(state.files,s,api.project(),{songLimit:s.music.length?musicLimit():undefined}),r=await fetch('./native-source/build-source-project.py');if(!r.ok)throw Error('Build helper unavailable.');result.files.set('studio/build-source-project.py',sourceBytes(await r.text()));await api.save(makeZip([...result.files]),'PokeBacon_'+s.engine+'_Source.zip');status('Source ZIP exported.');});}
 return{state,open,attach,attached};
}
async function loadImage(bytes){const url=URL.createObjectURL(new Blob([bytes],{type:'image/png'}));try{return await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Could not decode source PNG.'));image.src=url;});}finally{URL.revokeObjectURL(url);}}
function indexSourcePNG(bytes,rgba){const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);let palette;for(let at=8;at+12<=bytes.length;){const size=v.getUint32(at),tag=sourceText(bytes.subarray(at+4,at+8));if(at+12+size>bytes.length)throw Error('Invalid PNG chunk.');if(tag==='PLTE'){if(size>48||size%3)throw Error('Use at most 16 palette colours.');palette=Array.from({length:size/3},(_,i)=>'#'+Array.from(bytes.subarray(at+8+i*3,at+11+i*3),n=>n.toString(16).padStart(2,'0')).join(''));while(palette.length<16)palette.push('#000000');break;}at+=size+12;}if(palette){const colors=palette.map(c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16))),pixels=Array.from({length:rgba.length/4},(_,i)=>{if(rgba[i*4+3]<128)return 0;const n=colors.findIndex(c=>c.every((n,j)=>n===rgba[i*4+j]));if(n<0)throw Error('Pixels do not match the source palette.');return n;});return{palette,pixels};}const colors=new Set();for(let i=0;i<rgba.length;i+=4)if(rgba[i+3]>=128)colors.add(rgba[i]+','+rgba[i+1]+','+rgba[i+2]);if(colors.size>15)throw Error('Use at most 15 opaque colours plus transparency.');return indexRGBA(rgba,[],{extract:true});}
